import{_ as a,o as i,c as t,ag as s}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"导出到 OpenAPI","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/export-openapi.md","filePath":"zh/guide/export-openapi.md","lastUpdated":1785990345000}'),n={name:"zh/guide/export-openapi.md"};function o(p,e,r,l,d,h){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="导出到-openapi" tabindex="-1">导出到 OpenAPI <a class="header-anchor" href="#导出到-openapi" aria-label="Permalink to &quot;导出到 OpenAPI&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Beta 功能</p><p>OpenAPI 导出渠道默认关闭，使用前请先在 <strong>Features</strong> 标签页中启用。</p></div><p>EasyYapi 可以将 HTTP 接口导出为 <a href="https://www.openapis.org/" target="_blank" rel="noreferrer">OpenAPI</a> 3.0.3 文档。生成的文档可以交给 OpenAPI 工具处理、导入 API 网关，或作为 API 契约提交到代码仓库。</p><h2 id="启用渠道" tabindex="-1">启用渠道 <a class="header-anchor" href="#启用渠道" aria-label="Permalink to &quot;启用渠道&quot;">​</a></h2><p>打开 <strong>Settings</strong> &gt; <strong>Other Settings</strong> &gt; <strong>EasyApi</strong> &gt; <strong>Features</strong>，在 <strong>Export Channels</strong> 中启用 <strong>OpenAPI (Beta)</strong>。启用后，该渠道会出现在导出对话框和 OpenAPI 导出操作中。</p><h2 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to &quot;导出&quot;">​</a></h2><ol><li>打开包含 API 的文件，或在 Project 视图中选择文件/文件夹。</li><li>选择 <strong>EasyYapi</strong> &gt; <strong>Export</strong> &gt; <strong>OpenAPI (Beta)</strong>，也可以从 API Dashboard 使用 OpenAPI 操作。</li><li>如果 OpenAPI 设置中没有保存输出格式，按提示选择格式。</li><li>选择目标文件。</li></ol><p>JSON 默认写入 <code>openapi.json</code>，YAML 默认写入 <code>openapi.yaml</code>。可以在导出对话框中覆盖输出目录和文件名。</p><p>该渠道只支持 HTTP。由于此导出器不表示 gRPC，选择中的 gRPC 接口会被跳过。如果选择中没有 HTTP 接口，导出会提示没有可导出的内容。</p><h2 id="输出内容" tabindex="-1">输出内容 <a class="header-anchor" href="#输出内容" aria-label="Permalink to &quot;输出内容&quot;">​</a></h2><p>导出的 OpenAPI 3.0.3 文档包含：</p><ul><li><code>info.title</code>、<code>info.version</code> 和可选的描述</li><li>可选的 <code>servers</code> 地址</li><li>路径、操作和唯一的 operation ID</li><li>query、path、header、cookie 参数</li><li>JSON 请求体</li><li><code>application/x-www-form-urlencoded</code> 和 multipart 请求体，包括文件字段</li><li>响应结构和可复用的 components schema</li><li>从 API 文件夹或源代码类名生成的 tags</li><li>可用时导出枚举值和参数示例</li></ul><p>Path 参数始终标记为必填，这是 OpenAPI 规范的要求。没有返回模型的无返回值接口会输出为 <code>204 No content</code>。</p><h2 id="文档元数据规则" tabindex="-1">文档元数据规则 <a class="header-anchor" href="#文档元数据规则" aria-label="Permalink to &quot;文档元数据规则&quot;">​</a></h2><p>如果希望文档的基本信息不随本次导出的接口选择变化，可以在项目规则中设置：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">openapi.info.title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=Public API</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">openapi.info.version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2026.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">openapi.info.description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=HTTP API for the public application</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">openapi.server.url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://api.example.com</span></span></code></pre></div><p>推荐使用 <code>openapi.server.url</code> 设置服务器地址，也兼容旧的 <code>openapi.host</code>。<code>openapi.format.after</code> 事件会在文档构建完成、序列化之前执行，可用于在写入 JSON 或 YAML 前修改内存中的文档。</p><p>详见<a href="/zh/settings/config-rule">配置规则</a>。</p>`,18)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
